// Forked from https://www.shadertoy.com/view/wss3W2

// by SOK fractal Noise added

// Jan 2025

float rand(vec2 co){    return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);}

float hermite(float t)
{
  return t * t * (3.0 - 2.0 * t);
}

float noise(vec2 co, float frequency)
{
  vec2 v = vec2(co.x * frequency, co.y * frequency);

  float ix1 = floor(v.x);
  float iy1 = floor(v.y);
  float ix2 = floor(v.x + 1.0);
  float iy2 = floor(v.y + 1.0);

  float fx = hermite(fract(v.x));
  float fy = hermite(fract(v.y));

  float fade1 = mix(rand(vec2(ix1, iy1)), rand(vec2(ix2, iy1)), fx);
  float fade2 = mix(rand(vec2(ix1, iy2)), rand(vec2(ix2, iy2)), fx);

  return mix(fade1, fade2, fy);
}


float fnoise(vec2 co, float freq)
{
  float value = 0.0;
  for(int i=0 ; i<5 ; i++)
  {
    value += noise(co, freq);
    freq *= 2.0;
  }
  return value / float(5.);
}




vec3 FnoiseTexture(vec2 uv)
{
    // Normalized pixel coordinates (from 0 to 1)

    float value = fnoise(uv, 7.0);
    return vec3(value, value, value);
}

vec3 drawBrick(vec2 uv) 
{
    vec3 col = vec3(.5);

    // shadow
    vec2 mask2 = smoothstep(.1, .0, abs(uv - vec2(.52, .47)) - vec2(.8, .8) / 2.);
    col = mix(col, vec3(.3), mask2.x * mask2.y);

    // brick
    vec2 mask = smoothstep(.04, .0, abs(uv - .5) - vec2(.86, .8) / 2.);
    vec3 brickCol = mix(vec3(.57, .42, .3), vec3(.9, .64, .4), pow(uv.y, .7));



    vec3 fnoiseCol=vec3(1.);

    /// Timer Switch brick color normal and + fractal Noise 
    const float totalCount = 3.0;
    float current = mod(iTime, totalCount);    


    if(current<1.)
    {
    fnoiseCol=FnoiseTexture(uv);
    brickCol=mix(brickCol,fnoiseCol*2.,0.3);
    fnoiseCol=FnoiseTexture(uv*2.)*2.;
    }
    else 
    if(current<2.)
    {
    fnoiseCol=FnoiseTexture(uv);
    brickCol-=fnoiseCol*0.5;
    fnoiseCol=FnoiseTexture(uv*2.)*2.;
    }

    col = mix(col*fnoiseCol, brickCol, mask.x * mask.y);


    return col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) 
{
    vec2 uv = fragCoord/iResolution.xy;
    uv *= vec2(5.3, 7.); // brick size

    // pattern repetition (with x offset on even rows) 
    vec2 index = floor(uv);
    uv.x += step(.1, mod(index.y, 2.)) * .5;
    uv = fract(uv);
    vec3 col;
    col = drawBrick(uv);
    //col = vec3(uv, 0);

    // Output to screen
    fragColor = vec4(col,1.0);
}
